mapper.select:
SELECT p.* FROM wiki_plugin p LEFT JOIN wiki_plugin_version candidate ON candidate.id = ( SELECT pv.id FROM wiki_plugin_version pv WHERE pv.subject_id = p.id AND pv.tenant_id = p.tenant_id AND pv.is_deleted = 0 AND ( (pv.status = 'PENDING' AND pv.review_status IN ('PENDING', 'IN_PROGRESS')) OR (pv.status = 'DRAFT' AND pv.review_status = 'REJECTED') ) ORDER BY CASE WHEN pv.status = 'PENDING' THEN 0 ELSE 1 END, pv.id DESC LIMIT 1 ) WHERE p.is_deleted = 0
AND p.category = #{query.category}
AND ( p.name LIKE CONCAT('%', #{query.searchValue}, '%') OR p.plugin_key LIKE CONCAT('%', #{query.searchValue}, '%') )
AND COALESCE(candidate.review_status, p.status) = #{query.reviewStatus}
ORDER BY CASE COALESCE(candidate.review_status, p.status) WHEN 'PENDING' THEN 0 WHEN 'IN_PROGRESS' THEN 1 WHEN 'REJECTED' THEN 2 WHEN 'DONE' THEN 3 ELSE 4 END, COALESCE(candidate.update_time, p.update_time) DESC, p.id DESC
